def transform(grid):
    h, w = len(grid), len(grid[0])
    divider = next((r for r, row in enumerate(grid) if all(v == 2 for v in row)), None)
    if divider is None:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    # All 4s advance one row downward.
    for r in range(h - 2, -1, -1):
        for c in range(w):
            if grid[r][c] == 4:
                out[r][c] = 0
                out[r + 1][c] = 4

                # When a 4 reaches the cell immediately above the divider,
                # it leaves a widening diagonal trail behind it.
                if r + 1 == divider - 1:
                    for d in range(1, h):
                        rr = r + 1 - d
                        if rr < 0:
                            break
                        for cc in (c - d, c + d):
                            if 0 <= cc < w:
                                out[rr][cc] = 4
    return out
